import {
  Body,
  Container,
  Head as EmailHead,
  Html,
  Preview,
  Section,
  Row,
  Column,
  Heading,
  Text,
  Link,
  Img,
} from "jsx-email";
import { Fragment } from "react";

import { DefaultFonts } from "@/components/email/font-default";
import { EmailTailwind } from "@/components/email/email-theme";
import type { EmailTheme } from "@/components/email/email-theme";
import { emailAsset } from "@/components/email/email-assets";
import { defaultTheme } from "@/components/email/theme-default";

interface Cta_CTAWithTopLargeImageProps {
  theme?: EmailTheme;
  heading?: string;
  subtext?: string;
  ctaLabel?: string;
  ctaHref?: string;
  imageSrc?: string;
  imageAlt?: string;
  pageBackgroundColor?: string;
  backgroundColor?: string;
  headingColor?: string;
  textColor?: string;
  buttonBackgroundColor?: string;
  buttonTextColor?: string;
}

const Cta_fontFamily =
  'Inter, ui-sans-serif, system-ui, -apple-system, "Segoe UI", sans-serif';

const Cta_responsiveStyles = `
    @media only screen and (max-width: 599px) {
      .cta-top-image-content {
        padding-left: 24px !important;
        padding-right: 24px !important;
      }
    }

    .cta-top-image-button:hover {
      background-color: #4338ca !important;
    }
  `;

type Cta_SectionProps = Omit<Cta_CTAWithTopLargeImageProps, "theme">;

const Cta_defaultSectionProps = {
  backgroundColor: "#fffffe",
  buttonBackgroundColor: "#4f46e5",
  buttonTextColor: "#f8fafc",
  ctaHref: "https://example.com/",
  ctaLabel: "Activate & Save",
  heading: "Built for the journey ahead.",
  headingColor: "#030712",
  imageAlt: "",
  imageSrc: emailAsset("cta/cta-with-image-1.jpg"),
  pageBackgroundColor: "#f1f5f9",
  subtext:
    "You’re one step away from exploring our latest outdoor essentials. Confirm your email to complete your setup and get 10% off your first order.",
  textColor: "#4b5563",
} satisfies Cta_SectionProps;

const Cta_CTAWithTopLargeImageSection = (props: Cta_SectionProps) => {
  const resolved = { ...Cta_defaultSectionProps, ...props };
  return (
    <Section
      style={{ backgroundColor: resolved.pageBackgroundColor }}
      width="100%"
    >
      <Fragment>
        <Row>
          <Column>&zwj;</Column>
          <Column
            style={{
              backgroundColor: resolved.backgroundColor,
              maxWidth: "100%",
              paddingBottom: "44px",
              width: "600px",
            }}
          >
            <Section width="100%">
              <Fragment>
                <Row>
                  <Column
                    className="cta-top-image-content"
                    style={{ padding: "0 64px", textAlign: "center" }}
                  >
                    <Section style={{ lineHeight: "44px" }}>&zwj;</Section>
                    <Img
                      alt={resolved.imageAlt}
                      src={resolved.imageSrc}
                      style={{
                        borderRadius: "4px",
                        maxWidth: "100%",
                        verticalAlign: "middle",
                      }}
                      width="472"
                    />
                    <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
                    <Heading
                      style={{
                        color: resolved.headingColor,
                        fontFamily: Cta_fontFamily,
                        fontSize: "30px",
                        fontWeight: 500,
                        lineHeight: "36px",
                        margin: 0,
                        textAlign: "center",
                      }}
                      as="h2"
                    >
                      {resolved.heading}
                    </Heading>
                    <Section style={{ lineHeight: "24px" }}>&zwj;</Section>
                    <Text
                      style={{
                        color: resolved.textColor,
                        fontFamily: Cta_fontFamily,
                        fontSize: "16px",
                        fontWeight: 300,
                        lineHeight: "24px",
                        margin: 0,
                        textAlign: "center",
                      }}
                    >
                      {resolved.subtext}
                    </Text>
                    <Section style={{ lineHeight: "36px" }}>&zwj;</Section>
                    <Link
                      className="cta-top-image-button"
                      href={resolved.ctaHref}
                      style={{
                        backgroundColor: resolved.buttonBackgroundColor,
                        borderRadius: "8px",
                        color: resolved.buttonTextColor,
                        display: "inline-block",
                        fontFamily: Cta_fontFamily,
                        fontSize: "16px",
                        fontWeight: 500,
                        lineHeight: "24px",
                        padding: "10px 22px",
                        textAlign: "center",
                        textDecoration: "none",
                      }}
                    >
                      {resolved.ctaLabel}
                    </Link>
                  </Column>
                </Row>
              </Fragment>
            </Section>
          </Column>
          <Column>&zwj;</Column>
        </Row>
      </Fragment>
    </Section>
  );
};

const Cta_CTAWithTopLargeImage = ({
  pageBackgroundColor = "#f1f5f9",
  theme = defaultTheme,
  ...props
}: Cta_CTAWithTopLargeImageProps) => (
  <Html>
    <EmailHead>
      <DefaultFonts />
      <style dangerouslySetInnerHTML={{ __html: Cta_responsiveStyles }} />
    </EmailHead>
    <Preview>{props.heading ?? Cta_defaultSectionProps.heading}</Preview>
    <EmailTailwind theme={theme}>
      <Body
        style={{
          backgroundColor: pageBackgroundColor,
        }}
        className="font-sans m-0"
      >
        <Container className="mx-auto max-w-[600px] w-[600px]">
          <Cta_CTAWithTopLargeImageSection
            {...props}
            pageBackgroundColor={pageBackgroundColor}
          />
        </Container>
      </Body>
    </EmailTailwind>
  </Html>
);

Cta_CTAWithTopLargeImage.PreviewProps = {
  theme: defaultTheme,
} satisfies Cta_CTAWithTopLargeImageProps;

const __Cta = Cta_CTAWithTopLargeImage;

export interface TopImageCallToActionProps {
  theme?: Parameters<typeof __Cta>[0]["theme"];
  heading?: string;
  description?: string;
  action?: {
    href: string;
    label: string;
  };
  image?: {
    src: string;
    alt?: string;
  };
}

export const TopImageCallToAction = ({
  theme,
  heading,
  description,
  action,
  image,
}: TopImageCallToActionProps) => (
  <__Cta
    ctaHref={action?.href}
    ctaLabel={action?.label}
    heading={heading}
    imageAlt={image?.alt}
    imageSrc={image?.src}
    subtext={description}
    theme={theme}
  />
);

TopImageCallToAction.PreviewProps = {} satisfies TopImageCallToActionProps;

const ASSET_ORIGIN = "https://www.emailcn.run";

const palettes = [
  ["4F46E5", "FFFFFF"],
  ["0F766E", "FFFFFF"],
  ["C2410C", "FFFFFF"],
  ["7E22CE", "FFFFFF"],
  ["0369A1", "FFFFFF"],
  ["BE123C", "FFFFFF"],
] as const;

const hashString = (value: string) => {
  let hash = 7;

  for (const character of value) {
    hash = (hash * 31 + (character.codePointAt(0) ?? 0)) % 2_147_483_647;
  }

  return hash;
};

const getDimensions = (path: string) => {
  if (/(?:avatar|user|headshot)/i.test(path)) {
    return [160, 160] as const;
  }
  if (/(?:logo|insignia)/i.test(path)) {
    return [320, 96] as const;
  }
  if (/(?:badge-app|badge-google)/i.test(path)) {
    return [260, 80] as const;
  }
  if (/(?:icon|btc|eth)/i.test(path)) {
    return [64, 64] as const;
  }
  if (/(?:portrait|member|team)/i.test(path)) {
    return [600, 800] as const;
  }
  if (/(?:square|product|shopping-cart)/i.test(path)) {
    return [700, 700] as const;
  }
  if (/(?:hero|footer|background|bg-|overlay|full-width)/i.test(path)) {
    return [1200, 700] as const;
  }
  if (/(?:strip|landscape|bento|category-preview)/i.test(path)) {
    return [800, 520] as const;
  }

  return [800, 600] as const;
};

const getLabel = (path: string) => {
  const fileName = path.split("/").at(-1) ?? "emailcn";

  return fileName
    .replace(/\.[^.]+$/, "")
    .replace(/^(?:logo|badge|icon)-/, "")
    .replaceAll("-", " ")
    .replaceAll(/\b\w/g, (character) => character.toUpperCase());
};

const getSeed = (path: string) =>
  `emailcn-${path
    .replace(/\.[^.]+$/, "")
    .replaceAll(/[^a-z0-9]+/gi, "-")
    .replaceAll(/^-|-$/g, "")
    .toLowerCase()}`;

export const emailAsset = (path: string) => {
  const normalizedPath = path.replace(/^\/+/, "");

  if (
    normalizedPath === "bento-grids/trend.png" ||
    normalizedPath === "bento-grids/trend-sm.png"
  ) {
    return `${ASSET_ORIGIN}/email-assets/${normalizedPath}`;
  }

  const seed = getSeed(normalizedPath);
  const hash = hashString(seed);
  const [background, foreground] =
    palettes[hash % palettes.length] ?? palettes[0];
  const [width, height] = getDimensions(normalizedPath);

  if (/(?:avatar|user|headshot|member|team)/i.test(normalizedPath)) {
    return `https://api.dicebear.com/9.x/lorelei/png?seed=${encodeURIComponent(
      seed
    )}&size=${Math.max(width, height)}&backgroundColor=${background.toLowerCase()}`;
  }

  if (/(?:trend|chart)/i.test(normalizedPath)) {
    return `${ASSET_ORIGIN}/email-assets/bento-grids/trend.png`;
  }

  if (
    /(?:icon|btc|eth|logo|insignia|badge-app|badge-google)/i.test(
      normalizedPath
    )
  ) {
    return `https://placehold.co/${width}x${height}/${background}/${foreground}.png?text=${encodeURIComponent(
      getLabel(normalizedPath)
    )}`;
  }

  return `https://picsum.photos/seed/${encodeURIComponent(
    seed
  )}/${width}/${height}.jpg`;
};
